606	+/** How often an error showed after a pass. */
607	+export interface GlErrorCount {
608	+  pass: string;
609	+  /** The error's GL name, `INVALID_OPERATION`, or its number. */
610	+  error: string;
611	+  count: number;
612	+}
613	+
614	+const ERROR_NAMES = [
615	+  'INVALID_ENUM',
616	+  'INVALID_VALUE',
617	+  'INVALID_OPERATION',
618	+  'INVALID_FRAMEBUFFER_OPERATION',
619	+  'OUT_OF_MEMORY',
620	+  'CONTEXT_LOST_WEBGL',
621	+] as const;
622	+
623	+/**
624	+ * Errors read per check at most: a lost context answers every call with
625	+ * one, and the check must not spin on it.
626	+ */
627	+const MAX_ERRORS_PER_CHECK = 8;
628	+
629	+/**
630	+ * The GL errors of a context, counted by the pass they showed after - for
631	+ * the `?gldebug` diagnostic. Each check asks the GPU to catch up with what
632	+ * was queued, which stalls it, so nothing checks unless asked to.
633	+ */
634	+export class GlDiagnostics {
635	+  private readonly counts = new Map<string, GlErrorCount>();
636	+
637	+  public constructor(private readonly gl: WebGL2RenderingContext) {}
638	+
639	+  /** Takes the errors raised since the last check, as the pass's. */
640	+  public check(pass: string): void {
641	+    const gl = this.gl;
642	+    for (let read = 0; read < MAX_ERRORS_PER_CHECK; read++) {
643	+      const code = gl.getError();
644	+      if (code === gl.NO_ERROR) {
645	+        return;
646	+      }
647	+      const error = this.nameOf(code);
648	+      const key = `${pass}:${error}`;
649	+      const count = this.counts.get(key);
650	+      if (count == null) {
651	+        this.counts.set(key, { pass, error, count: 1 });
652	+      } else {
653	+        count.count++;
654	+      }
655	+    }
656	+  }
657	+
658	+  /** Every pass and error seen so far, in the order they first showed. */
659	+  public errors(): GlErrorCount[] {
660	+    return [...this.counts.values()].map((count) => ({ ...count }));
661	+  }
662	+
663	+  private nameOf(code: number): string {
664	+    const gl = this.gl as unknown as Record<string, unknown>;
665	+    return (
666	+      ERROR_NAMES.find((name) => gl[name] === code) ?? `0x${code.toString(16)}`
667	+    );
668	+  }
669	+}
670	+
671	+const DIAGNOSED = new WeakMap<WebGL2RenderingContext, GlDiagnostics>();
672	+
673	+/**
674	+ * Turns the diagnostic on for a context, for everything drawing in it - the
675	+ * painter and the GPU simulation - and hands back its diagnostics.
676	+ */
677	+export function diagnose(gl: WebGL2RenderingContext): GlDiagnostics {
678	+  let diagnostics = DIAGNOSED.get(gl);
679	+  if (diagnostics == null) {
680	+    diagnostics = new GlDiagnostics(gl);
681	+    DIAGNOSED.set(gl, diagnostics);
682	+  }
683	+  return diagnostics;
684	+}
685	+
686	+/** Checks for errors after a pass - only where the context is diagnosed. */
687	+export function checkGl(gl: WebGL2RenderingContext, pass: string): void {
688	+  DIAGNOSED.get(gl)?.check(pass);
689	+}
