881	+/**
882	+ * A WebGL2 context for specs that only care which calls were made: every
883	+ * method is a `jest.fn`, created on first use and recorded in `calls`. A
884	+ * constant (an upper-case name) is a number of its own. Objects come back
885	+ * as fresh `{}`, and checks pass: programs link, shaders compile,
886	+ * framebuffers are complete. `getError` gives the codes queued with
887	+ * `failNext`, then `NO_ERROR`.
888	+ */
889	+export interface FakeGl {
890	+  gl: WebGL2RenderingContext;
891	+  /** The calls made so far, by method name, with their arguments. */
892	+  calls: Map<string, unknown[][]>;
893	+  /** How often a method was called with these arguments. */
894	+  callsOf(name: string, ...args: unknown[]): number;
895	+  /** Queues an error for `getError`, after the ones already queued. */
896	+  failNext(code: number): void;
897	+  /** Queues an error for `getError` once that method is called next. */
898	+  failOn(method: string, code: number): void;
899	+}
900	+
901	+/** The value a constant of the fake context has. */
902	+export function glConstant(name: string): number {
903	+  let hash = 7;
904	+  for (let i = 0; i < name.length; i++) {
905	+    hash = (hash * 31 + name.charCodeAt(i)) >>> 0;
906	+  }
907	+  // Clear of NO_ERROR (0) and of small numbers a spec might use.
908	+  return 0x10000 + (hash % 0xffff);
909	+}
910	+
911	+const NO_ERROR = 0;
912	+
913	+export function fakeGl(): FakeGl {
914	+  const calls = new Map<string, unknown[][]>();
915	+  const errors: number[] = [];
916	+  const methods = new Map<string, jest.Mock>();
917	+  const failing = new Map<string, number>();
918	+  const results: Record<string, (...args: unknown[]) => unknown> = {
919	+    getProgramParameter: () => true,
920	+    getShaderParameter: () => true,
921	+    checkFramebufferStatus: () => glConstant('FRAMEBUFFER_COMPLETE'),
922	+    getUniformLocation: () => ({}),
923	+    getExtension: () => null,
924	+    getParameter: () => 'fake renderer',
925	+    isVertexArray: () => true,
926	+    isTexture: () => true,
927	+    getError: () => errors.shift() ?? NO_ERROR,
928	+  };
929	+  const target: Record<string | symbol, unknown> = { NO_ERROR };
930	+  const gl = new Proxy(target, {
931	+    get(_, name) {
932	+      if (typeof name !== 'string') {
933	+        return undefined;
934	+      }
935	+      if (name in target) {
936	+        return target[name];
937	+      }
938	+      if (/^[A-Z][A-Z0-9_]*$/.test(name)) {
939	+        return glConstant(name);
940	+      }
941	+      let method = methods.get(name);
942	+      if (method == null) {
943	+        const result =
944	+          results[name] ?? (() => (name.startsWith('create') ? {} : undefined));
945	+        method = jest.fn((...args: unknown[]) => {
946	+          const made = calls.get(name) ?? [];
947	+          made.push(args);
948	+          calls.set(name, made);
949	+          const failure = failing.get(name);
950	+          if (failure != null) {
951	+            failing.delete(name);
952	+            errors.push(failure);
953	+          }
954	+          return result(...args);
955	+        });
956	+        methods.set(name, method);
957	+      }
958	+      return method;
959	+    },
960	+  }) as unknown as WebGL2RenderingContext;
961	+  return {
962	+    gl,
963	+    calls,
964	+    callsOf: (name, ...args) =>
965	+      (calls.get(name) ?? []).filter((made) =>
966	+        args.every((arg, index) => Object.is(made[index], arg))
967	+      ).length,
968	+    failNext: (code) => errors.push(code),
969	+    failOn: (method, code) => failing.set(method, code),
970	+  };
971	+}
