1234	+/**
1235	+ * The GL diagnostic's sheet: the layers one under the other, each under a
1236	+ * row with its name, its colours on the left and its alpha beside them -
1237	+ * the glow packs colony ids into its alpha, so that is half of what to see.
1238	+ */
1239	+export function sheetLayout(
1240	+  layers: readonly Pick<CapturedLayer, 'label' | 'width' | 'height'>[]
1241	+): { width: number; height: number; placements: SheetPlacement[] } {
1242	+  let top = 0;
1243	+  const placements = layers.map(({ label, width, height }) => {
1244	+    const placement = {
1245	+      label,
1246	+      labelY: top,
1247	+      imageY: top + LABEL_HEIGHT,
1248	+      alphaX: width,
1249	+    };
1250	+    top += LABEL_HEIGHT + height;
1251	+    return placement;
1252	+  });
1253	+  return {
1254	+    width: Math.max(0, ...layers.map((layer) => layer.width * 2)),
1255	+    height: top,
1256	+    placements,
1257	+  };
1258	+}
1259	+
1260	+/** A layer's RGBA as its colours, opaque, and its alpha as grey. */
1261	+export function splitAlpha(pixels: Uint8Array): {
1262	+  colors: Uint8ClampedArray<ArrayBuffer>;
1263	+  alpha: Uint8ClampedArray<ArrayBuffer>;
1264	+} {
1265	+  const colors = new Uint8ClampedArray(pixels);
1266	+  const alpha = new Uint8ClampedArray(pixels.length);
1267	+  for (let i = 0; i < pixels.length; i += 4) {
1268	+    colors[i + 3] = 255;
1269	+    alpha.fill(pixels[i + 3], i, i + 3);
1270	+    alpha[i + 3] = 255;
1271	+  }
1272	+  return { colors, alpha };
1273	+}
1274	+
1275	+/** Draws the sheet of the layers - null where the canvas gives no 2D context. */
1276	+function drawSheet(layers: readonly CapturedLayer[]): HTMLCanvasElement | null {
1277	+  const { width, height, placements } = sheetLayout(layers);
1278	+  const canvas = document.createElement('canvas');
1279	+  canvas.width = width;
1280	+  canvas.height = height;
1281	+  const cx = canvas.getContext('2d');
1282	+  if (cx == null) {
1283	+    return null;
1284	+  }
1285	+  cx.fillStyle = '#000';
1286	+  cx.fillRect(0, 0, width, height);
1287	+  cx.font = `${LABEL_HEIGHT - 4}px monospace`;
1288	+  cx.textBaseline = 'top';
1289	+  layers.forEach((layer, index) => {
1290	+    const { label, labelY, imageY, alphaX } = placements[index];
1291	+    cx.fillStyle = '#fff';
1292	+    cx.fillText(
1293	+      `${label} (${layer.width}×${layer.height}) · alpha`,
1294	+      2,
1295	+      labelY + 2
1296	+    );
1297	+    const { colors, alpha } = splitAlpha(layer.pixels);
1298	+    cx.putImageData(
1299	+      new ImageData(colors, layer.width, layer.height),
1300	+      0,
1301	+      imageY
1302	+    );
1303	+    cx.putImageData(
1304	+      new ImageData(alpha, layer.width, layer.height),
1305	+      alphaX,
1306	+      imageY
1307	+    );
1308	+  });
1309	+  return canvas;
1310	+}
