1313	+ * Saves the layers as one PNG, `bacteria-gl-layers-<time>.png`, through the
1314	+ * browser's download - on a phone too, which has no dev tools to read them
1315	+ * with.
1316	+ */
1317	+export function downloadLayerSheet(layers: readonly CapturedLayer[]): void {
1318	+  if (layers.length === 0) {
1319	+    console.warn('GL layers: no GL painter is diagnosed, nothing to save');
1320	+    return;
1321	+  }
1322	+  const canvas = drawSheet(layers);
1323	+  if (canvas == null) {
1324	+    console.warn('GL layers: the browser gave no canvas to draw them on');
1325	+    return;
1326	+  }
1327	+  canvas.toBlob((blob) => {
1328	+    if (blob == null) {
